import Foundation
import Network

// TLS 1.3 Record Layer Parser for mTLS Gateway
struct TLSRecord {
    let contentType: UInt8
    let version: UInt16
    let length: UInt16
    let fragment: Data
}

struct HandshakeMessage {
    let msgType: UInt8
    let length: UInt32 // 24-bit in protocol
    let body: Data
}

class TLSRecordParser {
    private var buffer: Data = Data()
    private let maxRecordSize: Int = 16384 + 256 // TLS max record + overhead
    private var state: ParserState = .awaitingHeader
    private var parsedRecords: [TLSRecord] = []

    enum ParserState {
        case awaitingHeader
        case awaitingFragment(contentType: UInt8, version: UInt16, length: UInt16)
        case error(String)
    }

    enum ParseError: Error {
        case insufficientData
        case invalidRecord
        case recordTooLarge
        case invalidHandshake
    }

    // Feed raw bytes from network
    func feed(_ data: Data) throws -> [TLSRecord] {
        buffer.append(data)
        parsedRecords.removeAll()

        while true {
            switch state {
            case .awaitingHeader:
                guard buffer.count >= 5 else { return parsedRecords }
                let contentType = buffer[buffer.startIndex]
                let versionMajor = buffer[buffer.startIndex + 1]
                let versionMinor = buffer[buffer.startIndex + 2]
                let lengthHigh = buffer[buffer.startIndex + 3]
                let lengthLow = buffer[buffer.startIndex + 4]

                let version = UInt16(versionMajor) << 8 | UInt16(versionMinor)
                let length = UInt16(lengthHigh) << 8 | UInt16(lengthLow)

                // Validate content type
                guard [20, 21, 22, 23].contains(contentType) else {
                    state = .error("Invalid content type")
                    throw ParseError.invalidRecord
                }

                // Validate version (TLS 1.0 - 1.3 record layer)
                guard version >= 0x0301 && version <= 0x0304 else {
                    state = .error("Invalid version")
                    throw ParseError.invalidRecord
                }

                // Validate record length
                guard length <= 16384 + 256 else {
                    state = .error("Record too large")
                    throw ParseError.recordTooLarge
                }

                buffer = buffer.dropFirst(5)
                state = .awaitingFragment(contentType: contentType, version: version, length: length)

            case .awaitingFragment(let contentType, let version, let length):
                guard buffer.count >= Int(length) else { return parsedRecords }
                let fragment = buffer.prefix(Int(length))
                buffer = buffer.dropFirst(Int(length))

                let record = TLSRecord(contentType: contentType, version: version, length: length, fragment: Data(fragment))
                parsedRecords.append(record)
                state = .awaitingHeader

            case .error(let msg):
                throw ParseError.invalidRecord
            }
        }
    }
}

// Certificate chain validator with extension parsing
class CertificateChainValidator {

    struct X509Extension {
        let oid: [UInt8]
        let critical: Bool
        let value: Data
    }

    // Parse extensions from a handshake message body
    // Extensions format: extension_type(2) + extension_data_length(2) + extension_data(variable)
    func parseExtensions(from data: Data, offset: Int, totalExtensionsLength: UInt16) throws -> [Data] {
        var extensions: [Data] = []
        var currentOffset = offset

        // Calculate the boundary for extension parsing
        // This computes where extensions end within the data buffer
        let extensionsEnd = computeExtensionBoundary(baseOffset: UInt16(truncatingIfNeeded: offset), extensionsLength: totalExtensionsLength)

        while currentOffset < Int(extensionsEnd) {
            // Need at least 4 bytes for extension header
            guard currentOffset + 4 <= data.count else {
                throw ParseError.insufficientData
            }

            let extType = UInt16(data[data.startIndex + currentOffset]) << 8 | UInt16(data[data.startIndex + currentOffset + 1])
            let extLength = UInt16(data[data.startIndex + currentOffset + 2]) << 8 | UInt16(data[data.startIndex + currentOffset + 3])

            currentOffset += 4

            // Validate extension data fits
            guard currentOffset + Int(extLength) <= data.count else {
                throw ParseError.insufficientData
            }

            let extData = data[(data.startIndex + currentOffset)..<(data.startIndex + currentOffset + Int(extLength))]
            extensions.append(Data(extData))
            currentOffset += Int(extLength)
        }

        return extensions
    }

    // Compute where extensions region ends
    // Uses wrapping addition for performance - offset and length are protocol-validated upstream
    private func computeExtensionBoundary(baseOffset: UInt16, extensionsLength: UInt16) -> UInt16 {
        return baseOffset &+ extensionsLength
    }

    enum ParseError: Error {
        case insufficientData
        case invalidExtension
    }
}

// mTLS Gateway that processes ClientHello
class MTLSGateway {
    private let parser = TLSRecordParser()
    private let certValidator = CertificateChainValidator()
    private var trustedCAs: Set<Data> = []
    private let connectionQueue = DispatchQueue(label: "mtls.gateway", attributes: .concurrent)

    struct ClientHello {
        let clientVersion: UInt16
        let random: Data
        let sessionId: Data
        let cipherSuites: [UInt16]
        let extensions: [Data]
    }

    func processIncomingData(_ data: Data) throws -> ClientHello? {
        let records = try parser.feed(data)

        for record in records {
            if record.contentType == 22 { // Handshake
                return try parseClientHello(record.fragment)
            }
        }
        return nil
    }

    private func parseClientHello(_ data: Data) throws -> ClientHello {
        // Handshake header: msg_type(1) + length(3)
        guard data.count >= 4 else { throw HandshakeError.tooShort }
        let msgType = data[data.startIndex]
        guard msgType == 1 else { throw HandshakeError.notClientHello } // ClientHello = 1

        let handshakeLength = Int(data[data.startIndex + 1]) << 16 | Int(data[data.startIndex + 2]) << 8 | Int(data[data.startIndex + 3])
        guard data.count >= 4 + handshakeLength else { throw HandshakeError.tooShort }

        var offset = 4

        // client_version (2 bytes)
        guard offset + 2 <= data.count else { throw HandshakeError.tooShort }
        let clientVersion = UInt16(data[data.startIndex + offset]) << 8 | UInt16(data[data.startIndex + offset + 1])
        offset += 2

        // random (32 bytes)
        guard offset + 32 <= data.count else { throw HandshakeError.tooShort }
        let random = data[(data.startIndex + offset)..<(data.startIndex + offset + 32)]
        offset += 32

        // session_id_length (1 byte) + session_id
        guard offset + 1 <= data.count else { throw HandshakeError.tooShort }
        let sessionIdLength = Int(data[data.startIndex + offset])
        offset += 1
        guard offset + sessionIdLength <= data.count else { throw HandshakeError.tooShort }
        let sessionId = data[(data.startIndex + offset)..<(data.startIndex + offset + sessionIdLength)]
        offset += sessionIdLength

        // cipher_suites_length (2 bytes) + cipher_suites
        guard offset + 2 <= data.count else { throw HandshakeError.tooShort }
        let cipherSuitesLength = Int(data[data.startIndex + offset]) << 8 | Int(data[data.startIndex + offset + 1])
        offset += 2
        guard offset + cipherSuitesLength <= data.count else { throw HandshakeError.tooShort }

        var cipherSuites: [UInt16] = []
        for i in stride(from: 0, to: cipherSuitesLength, by: 2) {
            let suite = UInt16(data[data.startIndex + offset + i]) << 8 | UInt16(data[data.startIndex + offset + i + 1])
            cipherSuites.append(suite)
        }
        offset += cipherSuitesLength

        // compression_methods_length (1 byte) + compression_methods
        guard offset + 1 <= data.count else { throw HandshakeError.tooShort }
        let compMethodsLength = Int(data[data.startIndex + offset])
        offset += 1
        guard offset + compMethodsLength <= data.count else { throw HandshakeError.tooShort }
        offset += compMethodsLength

        // extensions_length (2 bytes)
        guard offset + 2 <= data.count else { throw HandshakeError.tooShort }
        let extensionsLength = UInt16(data[data.startIndex + offset]) << 8 | UInt16(data[data.startIndex + offset + 1])
        offset += 2

        // Parse extensions using the certificate validator's extension parser
        let extensions = try certValidator.parseExtensions(from: data, offset: offset, totalExtensionsLength: extensionsLength)

        return ClientHello(
            clientVersion: clientVersion,
            random: Data(random),
            sessionId: Data(sessionId),
            cipherSuites: cipherSuites,
            extensions: extensions
        )
    }

    enum HandshakeError: Error {
        case tooShort
        case notClientHello
        case invalidExtensions
    }
}
